Object.assign(window.KIOUKAN_EN || (window.KIOUKAN_EN = {}), {"Qui sont les deux menteurs ?":"Who are the two liars?","chronologie complète : désigne les deux menteurs":"timeline complete: pick the two liars","Deux menteurs":"Two liars","passage secret":"secret passage","porte fermée à clé":"locked door","arme":"weapon","panne":"power cut","dans le noir":"in the dark","chronologie complète : accuse le coupable":"timeline complete: accuse the culprit","Bravo, la campagne est terminée !":"Well done, the campaign is complete!","Le coupable et un complice mentent dans toutes leurs déclarations. Les autres disent vrai.":"The culprit and an accomplice lie in all their statements. The others tell the truth.","Les modes de jeu":"Game modes","La campagne 2 s’ouvre une fois les 42 épisodes de la campagne 1 terminés.":"Campaign 2 opens once the 42 episodes of campaign 1 are complete.","Reprendre la campagne 1":"Resume campaign 1","Campagne 2 · La Dernière Vente":"Campaign 2 · The Final Sale","Le plan":"The plan"});
